/**
 * AP Integration Directory block — server render (adapter).
 *
 * GENERATED by tools/gen-blocks.mjs from ui/components/integration-directory/component.json.
 * Do not edit by hand — change the contract and regenerate, or the block and
 * the kit will disagree about the schema.
 *
 * Maps the block's attributes into the kit's prop names and hands them to
 * ap_render_component(). No markup, no escaping, no styling here — all of that
 * lives in ui/components/integration-directory/.
 *
 * @var array    $attributes Block attributes.
 * @var string   $content    Inner block HTML (unused — this block has none).
 * @var WP_Block $block      Block instance (unused).
 *
 * @package AssetPandaGutenberg
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

$props = array(
	'anchor'             => $attributes['anchor'] ?? '',
	'eyebrow'            => $attributes['eyebrow'] ?? '',
	'title'              => $attributes['title'] ?? '',
	'title_accent'       => $attributes['title_accent'] ?? '',
	'lede'               => $attributes['lede'] ?? '',
	'categories_label'   => $attributes['categories_label'] ?? 'Categories',
	'categories'         => $attributes['categories'] ?? array(),
	'search_label'       => $attributes['search_label'] ?? 'Search integrations',
	'search_placeholder' => $attributes['search_placeholder'] ?? 'Search integrations...',
	'link_label'         => $attributes['link_label'] ?? 'Learn More',
	'per_page'           => $attributes['per_page'] ?? 12,
	'status_text'        => $attributes['status_text'] ?? 'Showing {from}–{to} of {total} integrations',
	'empty_text'         => $attributes['empty_text'] ?? 'No integrations match your search.',
	'empty_link_label'   => $attributes['empty_link_label'] ?? '',
	'empty_link_url'     => $attributes['empty_link_url'] ?? '',
	'reset_label'        => $attributes['reset_label'] ?? 'Show all integrations',
	'pager_label'        => $attributes['pager_label'] ?? 'Integration pages',
	'prev_label'         => $attributes['prev_label'] ?? 'Previous',
	'next_label'         => $attributes['next_label'] ?? 'Next',
	'page_label'         => $attributes['page_label'] ?? 'Page {page} of {pages}',
	'url_sync'           => $attributes['url_sync'] ?? true,
	'layout'             => $attributes['layout'] ?? 'default',
	'items'              => $attributes['items'] ?? array(),
);

$ap_html = ap_render_component( 'integration-directory', $props );

if ( '' === trim( (string) $ap_html ) ) {
	return;
}

/*
 * The wrapper carries the alignment class. Block themes put post content in a
 * constrained layout that clamps every direct child to the theme's content
 * width; `alignfull` is the documented escape hatch, and this block defaults
 * to it because AP sections are full-bleed bands. `align` is a block concern,
 * so it is deliberately absent from the props above.
 *
 * The same layouts also insert a block gap (margin-block-start) between
 * siblings. AP sections are designed flush — each paints its own background
 * edge to edge — so the gap would show as a strip of page background between
 * them. The zero margin is inline because the theme rule it beats is
 * zero-specificity; it styles the wrapper only, never the component.
 * Longhands on purpose: WordPress passes this through its safe-CSS allowlist,
 * which drops the margin-block shorthand and leaves an empty style="".
 */
printf(
	'<div %1$s>%2$s</div>',
	get_block_wrapper_attributes( array( 'style' => 'margin-top:0;margin-bottom:0' ) ), // phpcs:ignore WordPress.Security.EscapeOutput -- core-escaped attribute string.
	$ap_html // phpcs:ignore WordPress.Security.EscapeOutput -- kit escapes on output.
);
